def split_words(txt):
    # Check if there are any whitespaces in the input text
    if ' ' in txt:
        return txt.split()

    # If no whitespaces exist, check for commas
    elif ',' in txt:
        return txt.split(',')

    else:
        # Calculate the number of lower-case letters with odd order in the alphabet
        count = 0
        for char in txt:
            if 'a' <= char <= 'z':
                order = ord(char) - ord('a') + 1
                if order % 2 != 0:
                    count += 1
        return count

